export default async function install(app){const style=document.createElement('style');document.head.append(style);const update=()=>{const width=Math.max(0,Math.min(app.config.width,app.view.container.getBoundingClientRect().width-32));const css=`.esri-popup .esri-popup__main-container {width:${width}px!important;max-width:${width}px!important;} .esri-popup .esri-features {width:100%!important;max-width:100%!important;}`;if(style.textContent!==css)style.textContent=css;};const observer=new ResizeObserver(update);app.onCleanup(()=>{observer.disconnect();style.remove();});observer.observe(app.view.container);update();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const main=app.view.container.querySelector('.esri-popup__main-container');return {targetWidth:app.config.width,renderedWidth:main?.getBoundingClientRect().width,responsive:true};}